KG_CODE("f:tests/test_db8_recorder.py","\"\"\"db8 (owner order 2026-11-01, the db6 Item 5 Record button): a small icon-only Record button on\nthe dashboard that turns into a Stop square while it records everything the owner does (clicks,\nkeyboard, the time of each action, applications launched, commands typed into cmd or PowerShell),\nproduces the same kgrow.flow run document an agent run produces, and so Export -> Save -> Import ->\nPlay work unchanged and replay offline, without an agent.\n\nItem A red first: there is no b-record button, no /api/record route, no _run.record frame and no\n`recording` in the dashboard state.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\nfrom autoskill.daemon import Daemon\nfrom autoskill.protocol import Request\nfrom autoskill.safety.permissions import PermissionMode, PermissionPolicy, save_policy\n\nAPP_JS = Path(\"src/autoskill/dashboard/static/app.js\").read_text(encoding=\"utf-8\")\nINDEX_HTML = Path(\"src/autoskill/dashboard/static/index.html\").read_text(encoding=\"utf-8\")\nSTYLE_CSS = Path(\"src/autoskill/dashboard/static/style.css\").read_text(encoding=\"utf-8\")\n\n\nclass RecordButtonPageTests(unittest.TestCase):\n    \"\"\"The button: icon-only, a circle that becomes a square while recording (the owner's words).\"\"\"\n\n    def test_the_button_is_in_the_bar_with_both_icons(self):\n        self.assertIn('id=\"b-record\"', INDEX_HTML)\n        self.assertIn('class=\"btn icon\"', INDEX_HTML.split('id=\"b-record\"')[1][:60])\n        self.assertIn(\"<circle\", INDEX_HTML.split('id=\"b-record\"')[1][:300])       # the record circle\n        self.assertIn(\"<rect\", INDEX_HTML.split('id=\"b-record\"')[1][:300])         # the stop square\n\n    def test_the_face_flips_from_the_state_and_the_press_posts_it(self):\n        self.assertIn(\"setRecordFace\", APP_JS)\n        self.assertIn('r.recording && r.recording.active', APP_JS)                 # the state drives the face\n        self.assertIn('press(\"record\"', APP_JS)                                     # start/stop by the current face\n        self.assertIn('state: on ? \"stop\" : \"start\"', APP_JS)\n\n    def test_the_icon_morph_uses_the_theme_button_pattern(self):\n        self.assertIn(\"#b-record.recording .rec\", STYLE_CSS)\n        self.assertIn(\"#b-record:not(.recording) .stop\", STYLE_CSS)\n\n\nclass RecordFrameTests(unittest.TestCase):\n    \"\"\"_run.record start/stop and the recording flag in the state the page polls.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n        save_policy(self.home, PermissionPolicy(mode=PermissionMode.GUARDED))\n        self.d = Daemon(self.home)\n        self.addCleanup(self.d.shutdown)\n\n    def call(self, method, params=None):\n        return self.d.handle(Request(method=method, params=params or {}, id=\"t\"))\n\n    def test_start_and_stop_round_trip_in_the_state(self):\n        out = self.call(\"_run.record\", {\"state\": \"start\"})\n        self.assertTrue(out.ok, out.error)\n        self.assertTrue(out.result[\"recording\"])\n        state = self.call(\"_run.state\").result\n        self.assertTrue(state[\"recording\"][\"active\"])\n        out = self.call(\"_run.record\", {\"state\": \"stop\"})\n        self.assertTrue(out.ok, out.error)\n        self.assertFalse(out.result[\"recording\"])\n        state = self.call(\"_run.state\").result\n        self.assertFalse(state[\"recording\"][\"active\"])\n        self.assertEqual(self.d.confirmations.pending(), [])          # an owner press never asks (M123)\n\n    def test_a_second_start_is_refused_and_a_bad_state_too(self):\n        self.assertTrue(self.call(\"_run.record\", {\"state\": \"start\"}).ok)\n        again = self.call(\"_run.record\", {\"state\": \"start\"})\n        self.assertFalse(again.ok)\n        self.assertEqual(again.error[\"code\"], \"unsupported\")\n        bad = self.call(\"_run.record\", {\"state\": \"maybe\"})\n        self.assertFalse(bad.ok)\n\n    def test_the_frame_is_a_read(self):\n        from autoskill.safety.permissions import VERB_RISK, Risk\n        self.assertIs(VERB_RISK.get(\"_run.record\"), Risk.READ)\n\n    def test_the_stop_bumps_the_feed_so_the_page_sees_it_at_once(self):\n        self.call(\"_run.record\", {\"state\": \"start\"})\n        before = self.call(\"_run.state\").result[\"seq\"]\n        self.call(\"_run.record\", {\"state\": \"stop\"})\n        after = self.call(\"_run.state\").result[\"seq\"]\n        self.assertGreater(after, before)\n\n\nclass RecordRouteTests(unittest.TestCase):\n    \"\"\"/api/record reaches the frame with the state the page sent.\"\"\"\n\n    def test_the_route_reaches_the_frame(self):\n        from tests.test_db2_dashboard import _ServerCase\n\n        class Case(_ServerCase):\n            def runTest(self):\n                status, _, body = self.req(\"/api/record\", {\"state\": \"start\"})\n                self.assertEqual(status, 200)\n                self.assertEqual(self.calls[-1][0], \"_run.record\")\n                self.assertEqual(self.calls[-1][1], {\"state\": \"start\"})\n                self.assertIn(b\"ok\", body)     # the frame result's shape is covered by RecordFrameTests\n\n        result = unittest.TextTestRunner().run(unittest.TestSuite([Case(\"runTest\")]))\n        self.assertTrue(result.wasSuccessful(), \"the record route failed\")\n\n\n# --- Item B: the capture engine -----------------------------------------------------------\n\nCMD = {\"handle\": 111, \"title\": \"Command Prompt - python\", \"process\": \"cmd.exe\"}\nEXCEL = {\"handle\": 222, \"title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}\nNOTEPAD = {\"handle\": 333, \"title\": \"Notes - Notepad\", \"process\": \"notepad.exe\"}\n\n\ndef assembler(home):\n    from autoskill.recorder import Assembler\n    from autoskill.trajectory import Recorder\n    rec = Recorder(Path(home), \"20990101-010101-abcd\")\n    return Assembler(rec), rec\n\n\nclass AssemblerTests(unittest.TestCase):\n    \"\"\"Synthetic captured events become the same turn documents an agent run writes.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def type_text(self, a, text, win):\n        for ch in text:\n            a.key(ord(ch.upper()) if ch.isalpha() else 0x41, down=True, char=ch, win=win)\n            a.key(ord(ch.upper()) if ch.isalpha() else 0x41, down=False, char=ch, win=win)\n\n    def press(self, a, vk, win, char=None):\n        a.key(vk, down=True, char=char, win=win)\n        a.key(vk, down=False, char=char, win=win)\n\n    def test_a_command_typed_in_cmd_or_powershell_is_one_type_turn(self):\n        a, rec = assembler(self.home)\n        self.type_text(a, \"dir\", CMD)\n        self.press(a, 0x0D, CMD, char=\"\\n\")                     # Enter runs the command\n        a.flush()\n        turns = rec.turns()\n        self.assertEqual(len(turns), 1)\n        self.assertEqual(turns[0][\"tool\"], \"desktop.type\")\n        self.assertEqual(turns[0][\"arguments\"][\"text\"], \"dir\\n\")\n        self.assertEqual(turns[0][\"arguments\"][\"window\"], \"#111\")\n        self.assertEqual(turns[0][\"target\"][\"window\"],\n                         {\"handle\": \"#111\", \"window_title\": CMD[\"title\"], \"process\": \"cmd.exe\"})\n\n    def test_plain_text_flushes_on_the_next_click_and_carries_the_window(self):\n        a, rec = assembler(self.home)\n        self.type_text(a, \"Month\", EXCEL)\n        a.click(300, 400, EXCEL, {\"role\": \"button\", \"name\": \"Open\"})\n        a.flush()\n        turns = rec.turns()\n        self.assertEqual([t[\"tool\"] for t in turns], [\"desktop.type\", \"desktop.click\"])\n        self.assertEqual(turns[0][\"arguments\"][\"text\"], \"Month\")\n        self.assertEqual(turns[0][\"arguments\"][\"window\"], \"#222\")\n\n    def test_a_modifier_combo_is_one_key_turn(self):\n        a, rec = assembler(self.home)\n        a.key(0x11, down=True, win=EXCEL)                       # Ctrl down\n        self.press(a, 0x53, EXCEL, char=\"s\")                    # s\n        a.key(0x11, down=False, win=EXCEL)\n        a.flush()\n        turns = rec.turns()\n        self.assertEqual(turns[0][\"tool\"], \"desktop.key\")\n        self.assertEqual(turns[0][\"arguments\"][\"keys\"], \"ctrl+s\")\n        self.assertEqual(turns[0][\"arguments\"][\"window\"], \"#222\")\n\n    def test_a_click_with_element_identity_is_a_ref_click_for_replay(self):\n        a, rec = assembler(self.home)\n        a.click(300, 400, EXCEL, {\"role\": \"button\", \"name\": \"Save\"})\n        turns = rec.turns()\n        self.assertEqual(turns[0][\"tool\"], \"desktop.click\")\n        self.assertEqual(turns[0][\"arguments\"], {\"ref\": \"@e1\", \"delivery_mode\": \"foreground\"})\n        self.assertEqual(turns[0][\"target\"][\"ref\"], {\"ref\": \"@e1\", \"role\": \"button\", \"name\": \"Save\",\n                                                    \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"})\n\n    def test_a_click_without_identity_falls_back_to_screen_coordinates(self):\n        a, rec = assembler(self.home)\n        a.click(310, 422, EXCEL, None)\n        turns = rec.turns()\n        self.assertEqual(turns[0][\"tool\"], \"desktop.click_at\")\n        self.assertEqual(turns[0][\"arguments\"],\n                         {\"x\": 310, \"y\": 422, \"window\": \"#222\", \"delivery_mode\": \"foreground\"})\n\n    def test_a_new_application_window_is_an_open_app_turn(self):\n        a, rec = assembler(self.home)\n        a.app(\"EXCEL.EXE\", \"Book1 - Excel\")\n        turns = rec.turns()\n        self.assertEqual(turns[0][\"tool\"], \"desktop.open_app\")\n        self.assertEqual(turns[0][\"arguments\"][\"command\"], \"EXCEL.EXE\")\n        self.assertEqual(turns[0][\"arguments\"][\"wait_title\"], \"Book1 - Excel\")\n\n    def test_backspace_edits_the_typed_text(self):\n        a, rec = assembler(self.home)\n        self.type_text(a, \"Monh\", NOTEPAD)\n        self.press(a, 0x08, NOTEPAD)                             # Backspace drops the h\n        self.type_text(a, \"th\", NOTEPAD)\n        a.flush()\n        self.assertEqual(rec.turns()[0][\"arguments\"][\"text\"], \"Month\")\n\n    def test_text_does_not_leak_across_windows(self):\n        a, rec = assembler(self.home)\n        self.type_text(a, \"one\", EXCEL)\n        self.type_text(a, \"two\", NOTEPAD)\n        a.flush()\n        texts = [(t[\"arguments\"][\"text\"], t[\"arguments\"][\"window\"]) for t in rec.turns()]\n        self.assertEqual(texts, [(\"one\", \"#222\"), (\"two\", \"#333\")])\n\n    def test_every_turn_carries_the_time_of_the_action_and_a_client(self):\n        a, rec = assembler(self.home)\n        a.click(1, 2, EXCEL, None)\n        turn = rec.turns()[0]\n        self.assertIn(\"timestamp\", turn)\n        self.assertEqual(turn[\"outcome\"], \"ok\")\n        self.assertEqual(turn[\"effect\"], \"none\")                 # nothing was executed: no effect claimed\n        self.assertEqual(turn[\"client\"][\"name\"], \"record\")\n        self.assertFalse(turn[\"read_only\"])\n\n    def test_injected_events_are_not_the_owners_and_are_ignored(self):\n        a, rec = assembler(self.home)\n        a.key(0x53, down=True, char=\"s\", win=EXCEL, injected=True)\n        a.key(0x53, down=False, char=\"s\", win=EXCEL, injected=True)\n        a.click(1, 2, EXCEL, None, injected=True)\n        a.flush()\n        self.assertEqual(rec.turns(), [])                        # the run's own replay records itself\n\n\nclass WindowSkipTests(unittest.TestCase):\n    \"\"\"The dashboard, the studio and the tool's own windows are never a recording target.\"\"\"\n\n    def test_our_windows_are_skipped_and_the_owners_are_not(self):\n        from autoskill.recorder import should_skip_window\n        import os\n        self.assertTrue(should_skip_window(\"Kgrow.io\", \"Chrome_WidgetWin_1\", 999))\n        self.assertTrue(should_skip_window(\"Kgrow.io Studio\", \"Chrome_WidgetWin_1\", 999))\n        self.assertTrue(should_skip_window(\"Notes - Notepad\", \"Notepad\", os.getpid()))   # ours (overlay)\n        self.assertFalse(should_skip_window(\"Book1 - Excel\", \"XLMAIN\", 4242))\n        self.assertFalse(should_skip_window(\"Notes - Notepad\", \"Notepad\", 4242))\n\n\n# --- Item C: the recording joins Export -> Save -> Import -> Play, offline ------------------\n\nclass RecordingLifecycleTests(unittest.TestCase):\n    \"\"\"The finished recording is a run like any other: on the map, readable, saveable, playable -\n    with the desktop verbs stubbed at dispatch level so no real input is ever driven (R08).\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n        save_policy(self.home, PermissionPolicy(mode=PermissionMode.FULL))\n        self.d = Daemon(self.home)\n        self.addCleanup(self.d.shutdown)\n\n    def call(self, method, params=None):\n        return self.d.handle(Request(method=method, params=params or {}, id=\"t\"))\n\n    def record(self, *turns):\n        \"\"\"Start a real recording, feed resolved events straight to its assembler, stop it.\"\"\"\n        self.assertTrue(self.call(\"_run.record\", {\"state\": \"start\"}).ok)\n        active = self.d.human_recorder._active                      # noqa: SLF001 - the test's own module\n        a = active[\"assembler\"]\n        for turn in turns:\n            turn(a)\n        out = self.call(\"_run.record\", {\"state\": \"stop\"})\n        self.assertTrue(out.ok, out.error)\n        return out.result\n\n    def test_the_recording_lands_on_the_map_and_reads_back(self):\n        out = self.record(\n            lambda a: a.app(\"EXCEL.EXE\", \"Book1 - Excel\"),\n            lambda a: a.click(300, 400, EXCEL, {\"role\": \"button\", \"name\": \"Blank workbook\"}),\n            lambda a: a.key(0x4D, down=True, char=\"M\", win=EXCEL),\n        )\n        self.assertTrue(out[\"on_map\"])\n        self.assertEqual(out[\"turns\"], 3)\n        state = self.call(\"_run.state\").result\n        self.assertEqual(state[\"last_run\"][\"run_id\"], out[\"run_id\"])\n        self.assertEqual(state[\"run_id\"], out[\"run_id\"])            # Export and the steps panel use it\n        turns = self.call(\"_run.turns\", {\"run_id\": out[\"run_id\"]}).result[\"turns\"]\n        self.assertEqual([t[\"tool\"] for t in turns],\n                         [\"desktop.open_app\", \"desktop.click\", \"desktop.type\"])\n\n    def test_save_keeps_the_recording_as_a_flow_file(self):\n        out = self.record(lambda a: a.click(300, 400, EXCEL, {\"role\": \"button\", \"name\": \"Save\"}))\n        saved = self.call(\"_run.save\", {\"name\": \"recorded click\"}).result\n        self.assertEqual(saved[\"kind\"], \"run\")\n        import json\n        doc = json.loads((self.home / \"workflows\" / \"recorded click.kgrow.json\").read_text(\"utf-8\"))\n        self.assertEqual(doc[\"format\"], \"kgrow.flow\")\n        self.assertEqual(len(doc[\"turns\"]), 1)\n        self.assertEqual(doc[\"turns\"][0][\"target\"][\"ref\"][\"name\"], \"Save\")\n\n    def test_the_recorded_document_passes_the_offline_check(self):\n        from autoskill.workflowcheck import check_doc\n        out = self.record(\n            lambda a: a.app(\"EXCEL.EXE\", \"Book1 - Excel\"),\n            lambda a: a.click(300, 400, EXCEL, {\"role\": \"button\", \"name\": \"Blank workbook\"}),\n            lambda a: a.key(0x4D, down=True, char=\"M\", win=EXCEL),\n            lambda a: a.key(0x4D, down=False, char=\"M\", win=EXCEL),\n            lambda a: a.key(0x11, down=True, win=EXCEL),\n            lambda a: a.key(0x53, down=True, char=\"s\", win=EXCEL),\n            lambda a: a.key(0x11, down=False, win=EXCEL),\n        )\n        turns = self.call(\"_run.turns\", {\"run_id\": out[\"run_id\"]}).result[\"turns\"]\n        doc = {\"kind\": \"run\", \"name\": \"rec\", \"turns\": turns}\n        result = check_doc(doc)\n        errors = [f for f in result.get(\"findings\", []) if f.get(\"severity\") == \"error\"]\n        self.assertEqual(errors, [])\n\n    def test_play_runs_the_recording_again_through_the_daemon(self):\n        import time as _time\n        self.record(lambda a: a.click(300, 400, EXCEL, {\"role\": \"button\", \"name\": \"Save\"}))\n        dispatched = []\n        real_handle = self.d.handle\n\n        def stub(req):\n            from types import SimpleNamespace\n            if str(req.method or \"\").startswith(\"desktop.\"):\n                dispatched.append((req.method, dict(req.params or {})))\n                return SimpleNamespace(ok=True, error=None, result={\n                    \"effect_state\": \"committed\", \"text\": '@e9 button \"Save\"  \"Book1 - Excel\"',\n                    \"windows\": [{\"handle\": 999, \"title\": \"Book1 - Excel\"}]})\n            return real_handle(req)\n        self.d.handle = stub\n        out = self.call(\"_run.play\")\n        self.assertTrue(out.ok, out.error)\n        deadline = _time.monotonic() + 10\n        while _time.monotonic() < deadline and len(dispatched) < 2:\n            _time.sleep(0.05)\n        methods = [m for m, _p in dispatched]\n        self.assertIn(\"desktop.observe\", methods)                  # the identity is looked up again\n        click = [p for m, p in dispatched if m == \"desktop.click\"]\n        self.assertEqual(click, [{\"ref\": \"@e9\", \"delivery_mode\": \"foreground\"}])   # recorded delivery is preserved\n\n\n# --- db8 addendum 1: the owner's first real recording ---------------------------------------\n\nimport os\nfrom unittest.mock import patch\n\nfrom autoskill import recorder as rec_mod\n\n\nclass Addendum1Tests(unittest.TestCase):\n    \"\"\"Four defects the owner's own recording exposed (progress record, addendum 1).\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        self.a = Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"))\n\n    # 1 + 2: the window under a point is resolved to its ROOT before any skip check or identity\n\n    def test_the_owner_recorder_skips_the_click_by_the_root_window(self):\n        active = {\"assembler\": self.a}\n        calls = {}\n\n        def remember(key, value, answer):\n            calls[key] = value\n            return answer\n        with patch.object(rec_mod, \"_window_at\", return_value=5555), \\\n             patch.object(rec_mod, \"_root_window\", side_effect=lambda h: remember(\"root\", h, 7777)), \\\n             patch.object(rec_mod, \"_window_pid\", side_effect=lambda h: remember(\"pid\", h, 32804)), \\\n             patch.object(rec_mod, \"_window_title\", side_effect=lambda h: remember(\"title\", h, \"Kgrow.io\")), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"msedge.exe\"), \\\n             patch.object(rec_mod, \"_element_at\", return_value=None):\n            hr = rec_mod.HumanRecorder.__new__(rec_mod.HumanRecorder)\n            hr._on_mouse(active, {\"cx\": 11, \"cy\": 22, \"button\": \"left\", \"injected\": False})\n        self.assertEqual(calls[\"root\"], 5555)                       # the child is resolved to its root...\n        self.assertEqual(calls[\"pid\"], 7777)                        # ...and identity/skip use the ROOT\n        self.assertEqual(calls[\"title\"], 7777)\n        self.assertEqual(self.a.rec.turns(), [])                    # the dashboard click is not recorded\n\n    # 4: a click records the EVENT's own coordinates, not wherever the cursor is later\n\n    def test_a_click_records_the_events_own_point(self):\n        active = {\"assembler\": self.a}\n        with patch.object(rec_mod, \"_window_at\", return_value=8888), \\\n             patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h), \\\n             patch.object(rec_mod, \"_window_pid\", return_value=42), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Notes - Notepad\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"notepad.exe\"), \\\n             patch.object(rec_mod, \"_element_at\", return_value=None), \\\n             patch.object(rec_mod, \"_cursor_now\", return_value=(999, 999)):\n            hr = rec_mod.HumanRecorder.__new__(rec_mod.HumanRecorder)\n            hr._on_mouse(active, {\"cx\": 11, \"cy\": 22, \"button\": \"left\", \"injected\": False})\n            hr._on_mouse(active, {\"cx\": 12, \"cy\": 23, \"button\": \"left\", \"injected\": False, \"up\": True})\n        turn = self.a.rec.turns()[0]\n        self.assertEqual(turn[\"tool\"], \"desktop.click_at\")\n        self.assertEqual((turn[\"arguments\"][\"x\"], turn[\"arguments\"][\"y\"]), (11, 22))   # the PRESS's point\n\n    # 4: a key uses the foreground window captured with the event\n\n    def test_a_key_uses_the_window_captured_at_the_event(self):\n        import ctypes\n        active = {\"assembler\": self.a}\n        keystate = (ctypes.c_uint8 * 256)()\n        buf = ctypes.create_unicode_buffer(16)\n\n        def to_unicode(*_a):\n            buf.value = \"M\"\n            return 1\n        with patch.object(rec_mod, \"_window_pid\", return_value=42), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Book1 - Excel\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"), \\\n             patch.object(rec_mod, \"_foreground\", return_value=4242) as fg:\n            rec_mod.HumanRecorder.__new__(rec_mod.HumanRecorder)._on_key(\n                active, {\"vk\": 0x4D, \"scan\": 50, \"down\": True, \"injected\": False, \"hwnd\": 1717},\n                keystate, to_unicode, buf)\n        self.assertFalse(fg.called)                                 # no late foreground read\n        self.a.flush()\n        turn = self.a.rec.turns()[0]\n        self.assertEqual(turn[\"arguments\"][\"text\"], \"M\")\n        self.assertEqual(turn[\"arguments\"][\"window\"], \"#1717\")      # the event's captured window\n        self.assertEqual(turn[\"target\"][\"window\"][\"window_title\"], \"Book1 - Excel\")\n\n    # 3: the pointer's movement becomes the path of the click it leads to\n\n    def test_mouse_moves_become_the_path_of_the_next_click(self):\n        for x, y in ((10, 10), (20, 14), (35, 22)):\n            self.a.move(x, y)\n        self.a.click(300, 400, EXCEL, None)\n        turn = self.a.rec.turns()[-1]\n        self.assertEqual(turn.get(\"path\"), [[10, 10], [20, 14], [35, 22]])\n        # bounded, and the trail does not leak into the next click\n        for x in range(600):\n            self.a.move(x, 1)\n        self.a.click(301, 401, EXCEL, None)\n        turn2 = self.a.rec.turns()[-1]\n        self.assertLessEqual(len(turn2.get(\"path\") or []), 200)\n        # the moves before any click are dropped with the turn they never reached (recorded)\n\n    def test_a_move_only_sample_is_taken_while_the_pointer_travels(self):\n        self.a.move(1, 1)\n        self.a.move(1, 1)                                           # the same point again: not kept twice\n        self.a.click(300, 400, EXCEL, None)\n        self.assertEqual(self.a.rec.turns()[-1].get(\"path\"), [[1, 1]])\n\n\n# --- db8 addendum 7: the owner's live play - the Win key and child-window noise -------------\n\nclass Addendum7Tests(unittest.TestCase):\n    \"\"\"The owner played his imported \"excel task1\": it stopped at step 4 because his Windows-key\n    press that OPENED Search was never recorded (a standalone modifier was invisible state), and\n    the recording carried 11 close steps for Excel's internal child panels.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def assembler(self):\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        return Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"))\n\n    def test_a_standalone_win_key_is_recorded_as_the_step_that_opens_search(self):\n        a = self.assembler()\n        a.key(0x5B, down=True, win=CMD)          # Win down (opens the Start menu)\n        a.key(0x5B, down=False, win=CMD)         # Win up - alone: an ACTION, not invisible state\n        a.key(0x45, down=True, char=\"e\", win=CMD)\n        a.key(0x45, down=False, char=\"e\", win=CMD)\n        a.flush()\n        turns = a.rec.turns()\n        self.assertEqual(turns[0][\"tool\"], \"desktop.key\")\n        self.assertEqual(turns[0][\"arguments\"][\"keys\"], \"win\")          # the step replay needs\n        self.assertEqual(turns[0][\"arguments\"][\"window\"], \"#111\")\n        self.assertEqual(turns[0][\"arguments\"][\"delivery_mode\"], \"foreground\")\n        self.assertEqual(turns[0].get(\"wait_after_ms\"), 500)            # the Start menu opens\n\n    def test_a_modifier_in_a_combination_is_not_a_standalone_step(self):\n        a = self.assembler()\n        a.key(0x11, down=True, win=EXCEL)        # Ctrl down\n        a.key(0x53, down=True, char=\"s\", win=EXCEL)   # s -> ctrl+s\n        a.key(0x53, down=False, char=\"s\", win=EXCEL)\n        a.key(0x11, down=False, win=EXCEL)       # Ctrl up - was used: no standalone turn\n        a.flush()\n        self.assertEqual([t[\"tool\"] for t in a.rec.turns()], [\"desktop.key\"])\n        self.assertEqual(a.rec.turns()[0][\"arguments\"][\"keys\"], \"ctrl+s\")\n\n    def test_the_winevent_hook_ignores_child_panels(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"baseline\": set(), \"known\": {}}\n        with patch.object(rec_mod, \"_root_window\", return_value=999999):    # a child, not root\n            HumanRecorder.__new__(HumanRecorder)._on_win_event(\n                active, {\"t\": \"win_show\", \"hwnd\": 12345})\n        self.assertEqual(active[\"known\"], {})                            # never tracked\n\n    def test_the_winevent_hook_tracks_root_windows(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"baseline\": set(), \"known\": {}}\n        with patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h), \\\n             patch.object(rec_mod, \"_window_pid\", return_value=9), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Book1 - Excel\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n            HumanRecorder.__new__(HumanRecorder)._on_win_event(\n                active, {\"t\": \"win_show\", \"hwnd\": 12345})\n        entry = active[\"known\"][12345]\n        self.assertEqual(entry[:2], (\"Book1 - Excel\", \"EXCEL.EXE\"))   # addendum 8: + born time\n\n\n# --- db8 addendum 2: the imported \"excel\" workflow ------------------------------------------\n\nclass Addendum2Tests(unittest.TestCase):\n    \"\"\"The owner imported his second recording (the saved workflow \"excel\"): everything of\n    addendum 1 held (no leak, paths, root titles), but one step recorded Arabic characters - he\n    typed the KEYS of \"excel\" while an Arabic layout was active, and ToUnicodeEx answered with\n    the recording process's layout, not the focused window's own.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def assembler(self):\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        stamps = iter([\"2026-11-01T13:12:44\", \"2026-11-01T13:13:03\"])\n        return Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"),\n                         now=lambda: next(stamps)), stamps\n\n    def test_keys_translate_with_the_focused_windows_own_layout(self):\n        \"\"\"The hook captures the foreground window's keyboard layout; the translation must use\n        it (hkl), so an English-layout window answers \"e\" even under an Arabic system layout.\"\"\"\n        import ctypes\n        from autoskill import recorder as rec_mod\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        a = Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"))\n        active = {\"assembler\": a}\n        keystate = (ctypes.c_uint8 * 256)()\n        buf = ctypes.create_unicode_buffer(16)\n        calls = {}\n\n        def to_unicode(vk, scan, state, out, n, flags, hkl):\n            calls[\"hkl\"] = hkl\n            out.value = \"e\"\n            return 1\n        with patch.object(rec_mod, \"_window_pid\", return_value=42), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Search\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"SearchHost.exe\"):\n            rec_mod.HumanRecorder.__new__(rec_mod.HumanRecorder)._on_key(\n                active, {\"vk\": 0x45, \"scan\": 18, \"down\": True, \"injected\": False,\n                         \"hwnd\": 1717, \"hkl\": 987654}, keystate, to_unicode, buf)\n        self.assertEqual(calls[\"hkl\"], 987654)                      # the event's captured layout\n        a.flush()\n        self.assertEqual(a.rec.turns()[0][\"arguments\"][\"text\"], \"e\")\n\n    def test_a_typed_step_carries_the_time_typing_began(self):\n        \"\"\"The turn's timestamp is the FIRST character's moment (13:12:44), not the flush\n        (13:13:03, when the next click ended the typing).\"\"\"\n        a, _stamps = self.assembler()\n        a.key(0x4D, down=True, char=\"M\", win=EXCEL)\n        a.key(0x4D, down=False, char=\"M\", win=EXCEL)\n        a.click(300, 400, EXCEL, None)                             # flushes at the second stamp\n        turns = a.rec.turns()\n        self.assertEqual(turns[0][\"tool\"], \"desktop.type\")\n        self.assertEqual(turns[0][\"timestamp\"], \"2026-11-01T13:12:44\")\n        # the click keeps the real clock (the recorder's own), never the typing stamp\n        self.assertNotEqual(turns[1][\"timestamp\"], \"2026-11-01T13:12:44\")\n\n\n# --- db8 addendum 3: every action - scroll, drag, window close, hooks resilience ------------\n\nimport ctypes\n\n\nclass Addendum3Tests(unittest.TestCase):\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def assembler(self):\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        return Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"))\n\n    # scroll\n\n    def test_a_wheel_scroll_becomes_one_scroll_turn(self):\n        a = self.assembler()\n        a.scroll(\"down\", 3, EXCEL)\n        turn = a.rec.turns()[0]\n        self.assertEqual(turn[\"tool\"], \"desktop.scroll\")\n        self.assertEqual(turn[\"arguments\"], {\"direction\": \"down\", \"amount\": 3, \"window\": \"#222\",\n                                             \"delivery_mode\": \"foreground\"})\n        self.assertEqual(turn[\"target\"][\"window\"][\"window_title\"], \"Book1 - Excel\")\n\n    def test_wheel_direction_follows_the_delta_sign(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a}\n        with patch.object(rec_mod, \"_window_at\", return_value=222), \\\n             patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h), \\\n             patch.object(rec_mod, \"_window_pid\", return_value=9), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Book1 - Excel\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n            HumanRecorder.__new__(HumanRecorder)._on_wheel(active, {\"delta\": -240, \"cx\": 5, \"cy\": 5})\n        turn = a.rec.turns()[0]\n        # db8 addendum 9: Microsoft docs — negative delta = backward rotation (toward the\n        # user) = scroll DOWN. The old test had this inverted.\n        self.assertEqual(turn[\"arguments\"][\"direction\"], \"down\")\n        self.assertEqual(turn[\"arguments\"][\"amount\"], 2)\n\n    # drag\n\n    def test_a_press_release_far_apart_is_one_drag_in_window_coordinates(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"pending\": None}\n        with patch.object(rec_mod, \"_window_at\", return_value=222), \\\n             patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h), \\\n             patch.object(rec_mod, \"_window_pid\", return_value=9), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Book1 - Excel\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"), \\\n             patch.object(rec_mod, \"_window_rect\", return_value=(100, 200, 900, 700)), \\\n             patch.object(rec_mod, \"_element_at\", return_value=None):\n            hr = HumanRecorder.__new__(HumanRecorder)\n            hr._on_mouse(active, {\"cx\": 150, \"cy\": 250, \"button\": \"left\", \"injected\": False})\n            hr._on_mouse(active, {\"cx\": 450, \"cy\": 550, \"button\": \"left\", \"injected\": False, \"up\": True})\n        turns = a.rec.turns()\n        self.assertEqual(len(turns), 1)\n        self.assertEqual(turns[0][\"tool\"], \"desktop.drag\")\n        self.assertEqual(turns[0][\"arguments\"],\n                         {\"window\": \"#222\", \"from_x\": 50, \"from_y\": 50, \"to_x\": 350, \"to_y\": 350,\n                          \"delivery_mode\": \"foreground\"})\n\n    def test_a_press_release_close_together_stays_a_click(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"pending\": None}\n        with patch.object(rec_mod, \"_window_at\", return_value=222), \\\n             patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h), \\\n             patch.object(rec_mod, \"_window_pid\", return_value=9), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Book1 - Excel\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"), \\\n             patch.object(rec_mod, \"_window_rect\", return_value=(100, 200, 900, 700)), \\\n             patch.object(rec_mod, \"_element_at\", return_value=None):\n            hr = HumanRecorder.__new__(HumanRecorder)\n            hr._on_mouse(active, {\"cx\": 150, \"cy\": 250, \"button\": \"left\", \"injected\": False})\n            hr._on_mouse(active, {\"cx\": 152, \"cy\": 253, \"button\": \"left\", \"injected\": False, \"up\": True})\n        turns = a.rec.turns()\n        self.assertEqual([t[\"tool\"] for t in turns], [\"desktop.click_at\"])\n        self.assertEqual((turns[0][\"arguments\"][\"x\"], turns[0][\"arguments\"][\"y\"]), (150, 250))\n        self.assertEqual(turns[0][\"arguments\"][\"delivery_mode\"], \"foreground\")\n\n    # window close\n\n    def test_a_window_that_appeared_and_vanished_is_a_close_turn(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"baseline\": set(), \"launched\": set(), \"known\": {},\n                  \"poller_windows\": [\n                      [(222, 9, \"Book1 - Excel\")],          # appears\n                      [(222, 9, \"Book1 - Excel\")],          # still there\n                      [],                                    # gone -> a close turn\n                  ]}\n        with patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n        tools = [t[\"tool\"] for t in a.rec.turns()]\n        self.assertIn(\"desktop.open_app\", tools)             # the appearance\n        self.assertIn(\"desktop.close_window\", tools)         # the vanishing\n        close = [t for t in a.rec.turns() if t[\"tool\"] == \"desktop.close_window\"][0]\n        self.assertEqual(close[\"arguments\"], {\"window\": \"#222\"})\n        self.assertEqual(close[\"target\"][\"window\"][\"window_title\"], \"Book1 - Excel\")\n\n    def test_a_window_from_before_the_recording_is_not_recorded_as_closed(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"baseline\": {9}, \"launched\": set(), \"known\": {},\n                  \"poller_windows\": [[(222, 9, \"Book1 - Excel\")], []]}\n        with patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n        self.assertNotIn(\"desktop.close_window\", [t[\"tool\"] for t in a.rec.turns()])\n\n    # hooks resilience\n\n    def test_the_poller_reinstalls_the_hooks_when_their_thread_died(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        dead = type(\"H\", (), {\"alive\": lambda self: False, \"start\": lambda self: None, \"stop\": lambda self, t=1: None})()\n        active = {\"assembler\": a, \"baseline\": set(), \"launched\": set(), \"known\": {},\n                  \"poller_windows\": [[]], \"hooks\": dead, \"events\": None}\n        made = []\n        with patch.object(rec_mod, \"Hooks\", side_effect=lambda q: made.append(q) or type(\n                \"H2\", (), {\"alive\": lambda self: True, \"start\": lambda self: None,\n                           \"stop\": lambda self, t=1: None})()):\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n        self.assertEqual(len(made), 1)                       # a fresh hook was installed\n\n\n# --- db8 addendum 4: close steps must not stop a replay --------------------------------------\n\nclass Addendum4Tests(unittest.TestCase):\n    \"\"\"The owner's second real recording (31 steps): close steps for untitled or transient\n    windows would stop a replay whose targets no longer exist.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def recorder_active(self, windows_sequence):\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        a = Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"))\n        return a, {\"assembler\": a, \"baseline\": set(), \"launched\": {9},\n                   \"known\": {}, \"poller_windows\": windows_sequence}\n\n    def test_an_untitled_window_of_a_launched_app_is_never_a_close_step(self):\n        from autoskill.recorder import HumanRecorder\n        a, active = self.recorder_active([\n            [(222, 9, \"Book1 - Excel\"), (333, 9, \"\")],   # a titled and an untitled window\n            [(222, 9, \"Book1 - Excel\")],                 # the untitled one vanished\n        ])\n        with patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n        self.assertEqual([t[\"tool\"] for t in a.rec.turns()], [])     # nothing recorded at all\n\n    def test_a_close_step_carries_its_title_and_never_stops_a_replay(self):\n        from autoskill.recorder import HumanRecorder\n        a, active = self.recorder_active([\n            [(222, 9, \"Opening - Excel\")],\n            [],                                        # the splash vanished\n        ])\n        with patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n            HumanRecorder.__new__(HumanRecorder)._poll_once(active)\n        close = a.rec.turns()[-1]\n        self.assertEqual(close[\"tool\"], \"desktop.close_window\")\n        self.assertEqual(close[\"target\"][\"window\"][\"window_title\"], \"Opening - Excel\")\n        self.assertTrue(close[\"optional\"])             # a transient window must not stop Play\n\n    def test_an_optional_close_runs_and_the_next_target_still_runs(self):\n        from autoskill import trajectory\n        turns = [\n            {\"turn\": 1, \"tool\": \"desktop.close_window\", \"arguments\": {\"window\": \"#1\"}, \"optional\": True},\n            {\"turn\": 2, \"tool\": \"zz.type\", \"arguments\": {}},\n        ]\n        calls = []\n        out = trajectory.replay(lambda m, p: calls.append(m) or {\"effect_state\": \"committed\"}, turns, delay_ms=0)\n        self.assertEqual(calls, [\"desktop.close_window\", \"zz.type\"])\n        self.assertEqual((out[\"succeeded\"], out[\"skipped\"]), (2, 0))\n\n\n# --- db8 addendum 5: the owner's play - visible steps, true order ---------------------------\n\nclass Addendum5Tests(unittest.TestCase):\n    \"\"\"The owner played his imported workflow: \"it opened the excel then stopped... the Cursor\n    didn't move to do like as i did\". Three fixes: foreground delivery on every recorded input\n    step, turns reordered by their action time, and navigation keys ending the typed text.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def assembler(self, stamps):\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        it = iter(stamps)\n        return Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"),\n                         now=lambda: next(it))\n\n    def test_every_input_step_records_foreground_delivery(self):\n        a = self.assembler([\"T1\"] * 8)\n        a.click(1, 2, EXCEL, None)\n        a.click(3, 4, EXCEL, {\"role\": \"button\", \"name\": \"Save\"})\n        a.key(0x53, down=True, char=\"s\", win=EXCEL)\n        a.drag((1, 1), (50, 50), EXCEL)\n        a.scroll(\"down\", 2, EXCEL)\n        a.flush()\n        turns = a.rec.turns()\n        for turn in turns:\n            if turn[\"tool\"] != \"desktop.open_app\":\n                self.assertEqual(turn[\"arguments\"].get(\"delivery_mode\"), \"foreground\",\n                                 turn[\"tool\"])                  # the owner SEES every step\n        self.assertNotIn(\"delivery_mode\", [])                    # (open_app has none to check here)\n\n    def test_the_recorders_own_cursor_overlay_is_not_an_application_step(self):\n        a = self.assembler([\"T1\"])\n        a.app(\"cua-driver.exe\", \"Cua.AgentCursorOverlay.default\")\n        self.assertEqual(a.rec.turns(), [])\n\n    def test_turns_are_reordered_by_their_action_time_at_stop(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler([\"14:12:10\", \"14:12:15\", \"14:12:22\"])   # typing, launch, click\n        a.key(0x45, down=True, char=\"e\", win=CMD)                   # typed FIRST (flushes last)\n        a.key(0x45, down=False, char=\"e\", win=CMD)\n        a.app(\"EXCEL.EXE\", \"Excel\")                                 # written SECOND\n        a.click(5, 5, EXCEL, None)                                  # flushes the typing; written THIRD\n        daemon = type(\"D\", (), {\"home\": Path(self.home)})()\n        active = {\"recorder\": a.rec, \"assembler\": a}\n        hr = HumanRecorder.__new__(HumanRecorder)\n        hr.daemon = daemon\n        turns = hr._order_by_time(active)\n        order = [t[\"tool\"] for t in active[\"recorder\"].turns()]\n        self.assertEqual(order, [\"desktop.type\", \"desktop.open_app\", \"desktop.click_at\"])  # ACTION order\n        self.assertEqual(turns, 3)\n\n    def test_a_navigation_key_ends_the_text_so_order_survives(self):\n        a = self.assembler([\"T1\", \"T2\", \"T3\", \"T4\"])\n        a.key(0x41, down=True, char=\"a\", win=EXCEL)\n        a.key(0x28, down=True, win=EXCEL)                           # Down arrow\n        a.key(0x42, down=True, char=\"b\", win=EXCEL)\n        a.click(1, 1, EXCEL, None)\n        self.assertEqual([t[\"tool\"] for t in a.rec.turns()],\n                         [\"desktop.type\", \"desktop.key\", \"desktop.type\", \"desktop.click_at\"])\n        self.assertEqual(a.rec.turns()[0][\"arguments\"][\"text\"], \"a\")\n        self.assertEqual(a.rec.turns()[2][\"arguments\"][\"text\"], \"b\")\n\n\n# --- db8 addendum 8: the owner's overlay idea -----------------------------------------------\n\nclass Addendum8Tests(unittest.TestCase):\n    \"\"\"The owner: a green transparent layer while recording, the exact click coordinates,\n    the Win key without a window, and ephemeral windows filtered.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def assembler(self):\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        return Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"))\n\n    def test_the_win_key_is_recorded_even_with_no_focused_window(self):\n        \"\"\"The owner's play failed TWICE on this: the Win key opens Search from the DESKTOP,\n        where no titled window is focused — the old win-is-not-None guard silently dropped it.\"\"\"\n        a = self.assembler()\n        a.key(0x5B, down=True, win=None)         # the desktop: no window identity\n        a.key(0x5B, down=False, win=None)\n        a.flush()\n        turn = a.rec.turns()[0]\n        self.assertEqual(turn[\"tool\"], \"desktop.key\")\n        self.assertEqual(turn[\"arguments\"][\"keys\"], \"win\")            # the step, no window\n        self.assertNotIn(\"window\", turn[\"arguments\"])\n        self.assertEqual(turn.get(\"wait_after_ms\"), 500)\n\n    def test_every_click_carries_its_exact_screen_position(self):\n        \"\"\"The owner: 'it didn't record the Exact Positions of the clicks on the screen'.\"\"\"\n        a = self.assembler()\n        a.click(742, 319, EXCEL, {\"role\": \"button\", \"name\": \"Blank workbook\"})\n        a.click(100, 200, EXCEL, None)\n        turns = a.rec.turns()\n        self.assertEqual((turns[0][\"screen_x\"], turns[0][\"screen_y\"]), (742, 319))\n        self.assertEqual((turns[1][\"screen_x\"], turns[1][\"screen_y\"]), (100, 200))\n\n    def test_an_ephemeral_window_never_becomes_a_close_step(self):\n        \"\"\"The owner's 36-step recording carried 26 close steps for single-letter tooltips\n        (Excel's cell-reference popups) that lived for milliseconds.\"\"\"\n        import time as T\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"baseline\": set(), \"known\": {}}\n        active[\"known\"][222] = (\"F\", \"EXCEL.EXE\", T.monotonic() - 0.1)  # lived 0.1 s\n        with patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h):\n            HumanRecorder.__new__(HumanRecorder)._on_win_event(\n                active, {\"t\": \"win_gone\", \"hwnd\": 222})\n        self.assertEqual(a.rec.turns(), [])                    # ephemeral: not a step\n\n    def test_a_window_that_lived_two_seconds_is_a_close_step(self):\n        import time as T\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"baseline\": set(), \"known\": {}}\n        active[\"known\"][222] = (\"Book1 - Excel\", \"EXCEL.EXE\", T.monotonic() - 5.0)\n        with patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h):\n            HumanRecorder.__new__(HumanRecorder)._on_win_event(\n                active, {\"t\": \"win_gone\", \"hwnd\": 222})\n        close = a.rec.turns()[-1]\n        self.assertEqual(close[\"tool\"], \"desktop.close_window\")\n        self.assertEqual(close[\"target\"][\"window\"][\"window_title\"], \"Book1 - Excel\")\n\n    def test_the_green_overlay_shows_and_hides(self):\n        \"\"\"The owner's idea: a light green transparent layer while recording. On CI\n        (not Windows or no display) it returns False and the recording still works.\"\"\"\n        from autoskill.recorder import RecordingOverlay\n        overlay = RecordingOverlay()\n        overlay.show()                     # on this Windows machine: True; on CI: False\n        overlay.hide()                    # must never raise\n        self.assertTrue(True)             # reaching here is the test\n\n\nclass Addendum9Tests(unittest.TestCase):\n    \"\"\"Recording keeps lifecycle, click and terminal identity through Save -> Play.\"\"\"\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def assembler(self):\n        from autoskill.recorder import Assembler\n        from autoskill.trajectory import Recorder\n        return Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"))\n\n    def test_the_poller_preserves_the_winevent_born_time_shape(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"baseline\": set(), \"launched\": set(), \"known\": {},\n                  \"poller_windows\": [[(222, 9, \"Opening - Excel\")]]}\n        hr = HumanRecorder.__new__(HumanRecorder)\n        with patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n            hr._poll_once(active)\n        self.assertEqual(len(active[\"known\"][222]), 3)\n        active[\"known\"][222] = (*active[\"known\"][222][:2], 0.0)\n        with patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h), \\\n             patch.object(rec_mod.time, \"monotonic\", return_value=5.0):\n            hr._on_win_event(active, {\"t\": \"win_gone\", \"hwnd\": 222})\n        close = a.rec.turns()[-1]\n        self.assertEqual(close[\"tool\"], \"desktop.close_window\")\n        self.assertTrue(close[\"optional\"])\n\n    def test_stop_flush_preserves_a_pending_double_click(self):\n        import threading\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"stop\": threading.Event(), \"worker\": None, \"assembler\": a, \"recorder\": a.rec,\n                  \"hooks\": type(\"Hooks\", (), {\"stop\": lambda self: None})(),\n                  \"pending\": {\"x\": 10, \"y\": 20,\n                              \"win\": {\"handle\": 222, \"title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"},\n                              \"element\": None, \"at\": \"2026-11-01T19:51:47\", \"double\": True}}\n        HumanRecorder.__new__(HumanRecorder)._end_capture(active)\n        self.assertTrue(a.rec.turns()[-1][\"arguments\"][\"double\"])\n\n    def test_two_raw_click_pairs_become_a_typed_double_click(self):\n        from autoskill.recorder import HumanRecorder\n        a = self.assembler()\n        active = {\"assembler\": a, \"pending\": None}\n        with patch.object(rec_mod, \"_window_at\", return_value=222), \\\n             patch.object(rec_mod, \"_root_window\", side_effect=lambda h: h), \\\n             patch.object(rec_mod, \"_window_pid\", return_value=9), \\\n             patch.object(rec_mod, \"_window_title\", return_value=\"Book1 - Excel\"), \\\n             patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"), \\\n             patch.object(rec_mod, \"_element_at\", return_value=None), \\\n             patch.object(rec_mod, \"_double_click_contract\", return_value=(500, 8, 8)), \\\n             patch.object(rec_mod.time, \"monotonic\", side_effect=[0.0, 0.1, 0.2, 0.3]):\n            hr = HumanRecorder.__new__(HumanRecorder)\n            hr._on_mouse(active, {\"cx\": 150, \"cy\": 250, \"button\": \"left\", \"injected\": False})\n            hr._on_mouse(active, {\"cx\": 150, \"cy\": 250, \"button\": \"left\", \"injected\": False, \"up\": True})\n            hr._on_mouse(active, {\"cx\": 151, \"cy\": 251, \"button\": \"left\", \"injected\": False})\n            hr._on_mouse(active, {\"cx\": 151, \"cy\": 251, \"button\": \"left\", \"injected\": False, \"up\": True})\n        self.assertEqual([t[\"tool\"] for t in a.rec.turns()],\n                         [\"desktop.click_at\", \"desktop.click_at\"])\n        self.assertNotIn(\"double\", a.rec.turns()[0][\"arguments\"])\n        self.assertTrue(a.rec.turns()[1][\"arguments\"][\"double\"])\n\n    def test_a_coordinate_click_keeps_window_identity_and_pid(self):\n        a = self.assembler()\n        a.click(1859, 9, {\"handle\": 222, \"title\": \"Data (D:) - File Explorer\",\n                          \"process\": \"explorer.exe\", \"pid\": 42}, None)\n        turn = a.rec.turns()[-1]\n        self.assertEqual(turn[\"arguments\"][\"window\"], \"#222\")\n        self.assertEqual(turn[\"target\"][\"window\"],\n                         {\"handle\": \"#222\", \"window_title\": \"Data (D:) - File Explorer\",\n                          \"process\": \"explorer.exe\", \"pid\": 42})\n\n    def test_a_terminal_command_keeps_the_console_pid(self):\n        a = self.assembler()\n        console = dict(CMD, pid=42)\n        for ch in \"dir\":\n            a.key(ord(ch.upper()), down=True, char=ch, win=console)\n        a.key(0x0D, down=True, char=\"\\n\", win=console)\n        a.flush()\n        self.assertEqual(a.rec.turns()[0][\"target\"][\"window\"][\"pid\"], 42)\n\n    def test_open_app_uses_the_action_clock_and_preserves_true_order(self):\n        from autoskill.recorder import Assembler, HumanRecorder\n        from autoskill.trajectory import Recorder\n        stamps = iter([\"2026-11-01T19:51:40.100000\", \"2026-11-01T19:51:40.200000\",\n                       \"2026-11-01T19:51:40.300000\"])\n        a = Assembler(Recorder(Path(self.home), \"20990101-010101-abcd\"), now=lambda: next(stamps))\n        a.key(0x45, down=True, char=\"e\", win=CMD)\n        a.app(\"EXCEL.EXE\", \"Excel\")\n        a.click(5, 5, EXCEL, None)\n        daemon = type(\"D\", (), {\"home\": Path(self.home)})()\n        active = {\"recorder\": a.rec, \"assembler\": a}\n        hr = HumanRecorder.__new__(HumanRecorder)\n        hr.daemon = daemon\n        hr._order_by_time(active)\n        turns = active[\"recorder\"].turns()\n        self.assertEqual([t[\"tool\"] for t in turns],\n                         [\"desktop.type\", \"desktop.open_app\", \"desktop.click_at\"])\n        self.assertEqual(turns[1][\"timestamp\"], \"2026-11-01T19:51:40.200000\")\n\n    def test_the_default_action_clock_has_fractional_seconds(self):\n        a = self.assembler()\n        a.app(\"EXCEL.EXE\", \"Excel\")\n        a.click(5, 5, EXCEL, None)\n        self.assertRegex(a.rec.turns()[0][\"timestamp\"], r\"\\.\\d{6}$\")\n        self.assertRegex(a.rec.turns()[1][\"timestamp\"], r\"\\.\\d{6}$\")\n");
